CREATE TABLE users (id varchar(36) PRIMARY KEY, email varchar(254) NOT NULL UNIQUE, name varchar(100) NOT NULL, password_hash varchar(255), created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE identities (id varchar(36) PRIMARY KEY, user_id varchar(36) NOT NULL, provider varchar(20) NOT NULL, subject varchar(255) NOT NULL, UNIQUE(provider,subject), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE passkeys (id varchar(255) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id varchar(36) NOT NULL, public_key text NOT NULL, counter bigint unsigned NOT NULL, transports text NOT NULL, name varchar(100) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE sessions (id char(64) PRIMARY KEY, user_id varchar(36), csrf char(64) NOT NULL, verified_at bigint NOT NULL DEFAULT 0, expires_at bigint NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(expires_at));
CREATE TABLE challenges (session_id char(64) PRIMARY KEY, purpose varchar(30) NOT NULL, value varchar(255) NOT NULL, expires_at bigint NOT NULL, FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE);
